<?php
declare(strict_types=1);
require_once __DIR__.'/shared.php';
$db=acadDb();
$showArchived=($_GET['archived']??'')==='1';
try {
 $q=$db->query("SELECT r.request_id,r.status,r.reason,r.batch_id,r.submitted_at,r.reviewed_at,r.archived_at,p.program_code,ap.academic_year,ap.semester, su.username AS submitter,ru.username AS reviewer FROM academic_preview_requests r JOIN programs p ON p.program_id=r.program_id JOIN academic_periods ap ON ap.academic_period_id=r.academic_period_id JOIN auth_users su ON su.user_id=r.submitted_by LEFT JOIN auth_users ru ON ru.user_id=r.reviewed_by WHERE r.status IN ('APPROVED','REJECTED') AND r.deleted_at IS NULL AND r.archived_at IS ".($showArchived?'NOT NULL':'NULL')." ORDER BY r.reviewed_at DESC,r.request_id DESC LIMIT 500");
 $rows=$q->fetchAll(PDO::FETCH_ASSOC);
} catch(Throwable $e){ error_log('Approval history: '.$e->getMessage()); http_response_code(503);acadLayout('Approval History');echo '<h1>Approval history unavailable</h1><p>Run database/migrations/022_academic_preview_archive.sql in bcp_scheduling.</p>';acadEnd();exit; }
acadLayout('Approval History');
echo '<div class="eyebrow">ACADEMIC OFFICE · DECISION RECORDS</div><h1>Approval History</h1><p>Approved and rejected generated timetable submissions. View opens a read-only official-format document. Archive temporarily hides an entry; Delete removes it from office history without deleting any approved schedule or audit data.</p><div class="actions acad-history-tabs"><a class="btn '.(!$showArchived?'acad-tab-active':'secondary').'" href="history.php">Current history</a><a class="btn '.($showArchived?'acad-tab-active':'secondary').'" href="history.php?archived=1">Archived history</a></div><link rel="stylesheet" href="assets/history.css?v=20"><div class="panel scroll"><table><tr><th>Request</th><th>Program</th><th>Period</th><th>Decision</th><th>Saved batch</th><th>Reviewer</th><th>Reason / notes</th><th>Date</th><th>Actions</th></tr>';
foreach($rows as $r){
 echo '<tr><td>#'.(int)$r['request_id'].'</td><td>'.acadH($r['program_code']).'</td><td>'.acadH($r['academic_year']).' Sem '.(int)$r['semester'].'</td><td>'.acadH($r['status']).'</td><td>'.acadH($r['batch_id']??'Not saved').'</td><td>'.acadH($r['reviewer']??'').'</td><td>'.acadH($r['reason']??'').'</td><td>'.acadH($r['reviewed_at']??'').'</td><td><a class="btn secondary" href="document-view.php?id='.(int)$r['request_id'].'" data-document-view="'.(int)$r['request_id'].'">View</a> <form method="post" action="preview-archive.php" style="display:inline"><input type="hidden" name="csrf_token" value="'.acadH(authCsrf()).'"><input type="hidden" name="id" value="'.(int)$r['request_id'].'"><input type="hidden" name="action" value="'.($showArchived?'restore':'archive').'"><button type="submit" class="btn secondary" onclick="return confirm(\'This only '.($showArchived?'restores':'archives').' the history entry; saved schedules are not deleted. Continue?\')">'.($showArchived?'Restore':'Archive').'</button></form> <form method="post" action="preview-archive.php" style="display:inline"><input type="hidden" name="csrf_token" value="'.acadH(authCsrf()).'"><input type="hidden" name="id" value="'.(int)$r['request_id'].'"><input type="hidden" name="action" value="delete"><button type="submit" class="btn secondary" onclick="return confirm(\'Remove this entry from Academic Office history? This cannot be restored in the UI. Approved schedules will NOT be deleted.\')">Delete</button></form></td></tr>';
}
if(!$rows)echo '<tr><td colspan="9">No '.($showArchived?'archived':'completed').' requests.</td></tr>';
echo '</table></div>'; include __DIR__.'/document-modal.php'; acadEnd();
